function render(){document.documentElement.lang=state.uiLang;document.body.dataset.theme=state.theme;document.querySelector('meta[name="theme-color"]').content=state.theme==='dark'?'#0b1022':'#f3f6ff';document.getElementById('app').innerHTML=appHtml();document.getElementById('modal-root').innerHTML=modalHtml();}
function restoreDemo(){state.image&&URL.revokeObjectURL(state.image);state.crop={x:0,y:0,w:1,h:1};state.puzzleLang=state.uiLang;state.manualCells=[];loadDemo(state.uiLang);solve();render();}
function setImage(file){if(!file)return;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024){notify(tt('failedFile'));return;}
 if(state.image)URL.revokeObjectURL(state.image);
 state.image=URL.createObjectURL(file);state.imageName=file.name;state.crop={x:0,y:0,w:1,h:1};state.grid=[];state.gridRaw='';state.wordBank='';state.found=[];state.ocrWarning='';state.query='';state.intent=null;state.searchMatches=null;state.letterFilter='';state.boardEdit=false;state.mode='image';state.selectedId='';state.manualCells=[];state.visible=true;state.modal='crop';render();notify(tt('photoReady'));
}
async function analyze(){if(state.working)return;
 if(!state.image){notify(tt('imageFirst'));document.getElementById('file-input')?.click();return;}
 state.working=true;state.progress=0;render();
 try{const {gridText}=await recognizePuzzle(state.image,state.crop,locale(state.puzzleLang).ocr,value=>{
  state.progress=value;const f=document.getElementById('progress-fill'),l=document.getElementById('progress-label');if(f)f.style.width=value+'%';if(l)l.textContent=value+'%';},{rows:state.ocrRows,cols:state.ocrCols});
  state.gridRaw=gridText;state.grid=parseGrid(gridText);state.manualCells=[];state.ocrWarning=gridText.includes(' X ')?'Review uncertain OCR cells in the grid editor.':'';if(!state.grid.length)throw new Error('grid-empty');state.query='';state.intent=null;state.selectedId='';solve();notify(tt('doneOCR'));
 }catch(error){console.error('SopaLens OCR:',error);notify(state.uiLang==='es'?'No se pudo leer la cuadrícula con precisión. Revisa el recorte o edita las letras.':'OCR failed. Review the crop or edit the grid.');state.modal='crop';}
 finally{state.working=false;render()}
}
async function applySearch(query){
 state.query=String(query||'').trim();state.searchMatches=null;state.letterFilter='';
 if(!state.query){state.intent=null;state.selectedId='';render();return;}
 const raw=normalized(state.query),rawUnits=graphemes(raw);
 if(rawUnits.length===1){state.intent=null;state.letterFilter=raw;state.selectedId='';state.visible=false;render();return;}
 if(rawUnits.length>=2 && rawUnits.length<=Math.max(state.grid.length,state.grid[0]?.length||0) && /^[\p{L}\p{M}]+$/u.test(raw)){
  const sequenceMatches=findWords(state.grid,[raw],{});
  if(sequenceMatches.length){state.searchMatches=sequenceMatches;state.intent=null;state.selectedId='';state.visible=true;render();return;}
  if(rawUnits.length<=3){state.searchMatches=[];state.intent=null;state.selectedId='';state.visible=true;render();return;}
 }
 let intent=parseIntent(state.query);
 if(!intent.understood){const exact=state.found.find(x=>x.word===raw);if(exact){intent.exact=exact.word;intent.understood=true;}}
 if(!intent.understood){try{
  const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),5000);
  try {const res=await fetch('/api/interpret',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:state.query,language:state.uiLang}),signal:controller.signal});if(res.ok){const data=await res.json();if(data&&data.understood)intent={...intent,...data,understood:true};}}
  finally{clearTimeout(timeout)}
 }catch{/* Optional server-side AI is absent; offline filters still work. */}}
 if(!intent.understood){notify(tt('queryUnknown'));state.intent=null;render();return;}
 state.intent=intent;state.selectedId='';state.visible=true;render();}

function exportGridPng(grid,placements,filename,withAnswers){if(!grid?.length)return;
 const size=70,pad=42,cols=grid[0].length,rows=grid.length;const canvas=document.createElement('canvas');canvas.width=cols*size+pad*2;canvas.height=rows*size+pad*2+60;const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#172044';ctx.font='800 28px sans-serif';ctx.fillText('SopaLens',pad,37);ctx.fillStyle='#f6f8fd';ctx.fillRect(pad,pad+17,cols*size,rows*size);ctx.strokeStyle='#dfe6f3';ctx.lineWidth=1;for(let r=0;r<=rows;r++){ctx.beginPath();ctx.moveTo(pad,pad+17+r*size);ctx.lineTo(pad+cols*size,pad+17+r*size);ctx.stroke();}for(let c=0;c<=cols;c++){ctx.beginPath();ctx.moveTo(pad+c*size,pad+17);ctx.lineTo(pad+c*size,pad+17+rows*size);ctx.stroke();}if(withAnswers)placements.forEach((w,i)=>{const a=w.cells[0],b=w.cells.at(-1);ctx.beginPath();ctx.moveTo(pad+(a.c+.5)*size,pad+17+(a.r+.5)*size);ctx.lineTo(pad+(b.c+.5)*size,pad+17+(b.r+.5)*size);ctx.lineCap='round';ctx.lineWidth=size*.72;ctx.strokeStyle=COLORS[i%COLORS.length]+'80';ctx.stroke();});ctx.fillStyle='#101c38';ctx.font='800 31px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';grid.forEach((row,r)=>row.forEach((letter,c)=>ctx.fillText(letter,pad+(c+.5)*size,pad+17+(r+.5)*size)));ctx.textAlign='left';ctx.font='14px sans-serif';ctx.fillStyle='#68738d';ctx.fillText('sopalens · '+placements.length+' '+tt('statsWords'),pad,canvas.height-13);canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob);const a=document.createElement('a');a.download=filename;a.href=url;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(tt('exported'));},'image/png');}
function exportPng(){if(!state.grid.length)return;
 const size=70,pad=42,cols=state.grid[0].length,rows=state.grid.length;
 const canvas=document.createElement('canvas');canvas.width=cols*size+pad*2;canvas.height=rows*size+pad*2+60;
 const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);
 ctx.fillStyle='#172044';ctx.font='800 28px sans-serif';ctx.fillText('SopaLens',pad,37);
 ctx.fillStyle='#f6f8fd';ctx.fillRect(pad,pad+17,cols*size,rows*size);
 ctx.strokeStyle='#dfe6f3';ctx.lineWidth=1;
 for(let r=0;r<=rows;r++){ctx.beginPath();ctx.moveTo(pad,pad+17+r*size);ctx.lineTo(pad+cols*size,pad+17+r*size);ctx.stroke();}
 for(let c=0;c<=cols;c++){ctx.beginPath();ctx.moveTo(pad+c*size,pad+17);ctx.lineTo(pad+c*size,pad+17+rows*size);ctx.stroke();}
 if(state.visible)matched().forEach(w=>{const a=w.cells[0],b=w.cells.at(-1);ctx.beginPath();ctx.moveTo(pad+(a.c+.5)*size,pad+17+(a.r+.5)*size);ctx.lineTo(pad+(b.c+.5)*size,pad+17+(b.r+.5)*size);ctx.lineCap='round';ctx.lineWidth=size*.72;ctx.strokeStyle=COLORS[state.found.indexOf(w)%COLORS.length]+'80';ctx.stroke();});
 ctx.fillStyle='#101c38';ctx.font='800 31px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';
 state.grid.forEach((row,r)=>row.forEach((letter,c)=>ctx.fillText(letter,pad+(c+.5)*size,pad+17+(r+.5)*size)));
 ctx.textAlign='left';ctx.font='14px sans-serif';ctx.fillStyle='#68738d';ctx.fillText('sopalens · '+matched().length+' '+tt('statsWords'),pad,canvas.height-13);
 canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob);const a=document.createElement('a');a.download='SopaLens-solucion.png';a.href=url;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(tt('exported'));},'image/png');
}
function pointerPos(e,rect){return {x:Math.min(1,Math.max(0,(e.clientX-rect.left)/rect.width)),y:Math.min(1,Math.max(0,(e.clientY-rect.top)/rect.height))}}
function handleCropStart(e){if(e.button!==0)return;const stage=e.target.closest('#crop-stage');if(!stage)return;dragStart={start:pointerPos(e,stage.getBoundingClientRect()),id:e.pointerId};stage.setPointerCapture?.(e.pointerId);}
function handleCropMove(e){if(!dragStart)return;const stage=e.target.closest('#crop-stage')||document.getElementById('crop-stage');if(!stage)return;const point=pointerPos(e,stage.getBoundingClientRect()),start=dragStart.start;
 const x=Math.min(point.x,start.x),y=Math.min(point.y,start.y),w=Math.abs(point.x-start.x),h=Math.abs(point.y-start.y);
 const overlay=stage.querySelector('.crop-overlay');if(overlay){overlay.style.left=x*100+'%';overlay.style.top=y*100+'%';overlay.style.width=w*100+'%';overlay.style.height=h*100+'%';}
}
function handleCropEnd(e){if(!dragStart)return;const stage=e.target.closest('#crop-stage')||document.getElementById('crop-stage');if(!stage)return;const end=pointerPos(e,stage.getBoundingClientRect()),start=dragStart.start;
 const x=Math.min(start.x,end.x),y=Math.min(start.y,end.y),w=Math.abs(start.x-end.x),h=Math.abs(start.y-end.y);
 if(w>.08&&h>.08)state.crop={x,y,w,h};dragStart=null;render();}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';try{localStorage.setItem('sopalens.theme',state.theme)}catch{}render();}
function setLang(kind,code){if(!LANGUAGES.some(l=>l.code===code))return;
 if(kind==='ui'){state.uiLang=code;state.puzzleLang=code;state.manualCells=[];try{localStorage.setItem('sopalens.uiLang',code)}catch{}if(state.mode==='demo')loadDemo(code);state.searchMatches=null;state.letterFilter='';state.intent=null;state.query='';solve();}
 if(kind==='puzzle'){state.puzzleLang=code;state.searchMatches=null;state.letterFilter='';solve();}state.openMenu='';render();}
function handleClick(e){const target=e.target.closest('button,[data-word],[data-suggest],[data-set-lang],[data-menu],[data-manual-cell],[data-generator-size],[data-generator-difficulty],[data-generator-dropdown]');
 if(!target){if(state.openMenu&&!e.target.closest('.dropdown-shell,.generator-select-shell')){state.openMenu='';render()}return;}
 const {id,dataset}=target;
 if(dataset.manualCell!==undefined){const key=dataset.manualCell;state.manualCells=state.manualCells.includes(key)?state.manualCells.filter(item=>item!==key):[...state.manualCells,key];render();return;}
 if(dataset.generatorDropdown){const menu=`generator-${dataset.generatorDropdown}`;state.openMenu=state.openMenu===menu?'':menu;render();return;}
 if(dataset.generatorSize!==undefined){state.createSize=dataset.generatorSize;state.openMenu='';render();return;}
 if(dataset.generatorDifficulty!==undefined){state.createDifficulty=dataset.generatorDifficulty;state.openMenu='';render();return;}
 if(dataset.menu){state.openMenu=state.openMenu===dataset.menu?'':dataset.menu;render();return;}
 if(dataset.setLang){const [kind,code]=dataset.setLang.split(':');setLang(kind,code);return;}
 if(dataset.word){state.selectedId=state.selectedId===dataset.word?'':dataset.word;state.visible=true;render();return;}
 if(dataset.removeWord!==undefined){const words=splitWordBank(state.wordBank);words.splice(Number(dataset.removeWord),1);state.wordBank=words.join('\n');render();return;}
 if(dataset.suggest!==undefined){const index=Number(dataset.suggest),labels=tt('suggestions');const intents=[{contains:'C'},{category:'animals'},{direction:'diagonal'},{length:5}];state.query=labels[index]||'';state.intent={query:state.query,contains:'',starts:'',ends:'',length:null,direction:'',category:'',exact:'',understood:true,...intents[index]};state.searchMatches=null;state.letterFilter='';state.selectedId='';state.visible=true;render();return;}
 switch(id){case 'theme-toggle':case 'modal-theme':toggleTheme();break;
 case 'mode-solve':state.appMode='solve';state.manualCells=[];render();break;
 case 'mode-create':state.appMode='create';state.manualCells=[];render();break;
 case 'toggle-generated-answers':state.showGeneratedAnswers=!state.showGeneratedAnswers;render();break;
 case 'download-generated-puzzle':exportGridPng(state.generated?.grid||[],state.generated?.placements||[],'SopaLens-pupiletras.png',false);break;
 case 'download-generated-answers':exportGridPng(state.generated?.grid||[],state.generated?.placements||[],'SopaLens-respuestas.png',true);break;
 case 'open-crop':state.modal='crop';state.openMenu='';render();break;
 case 'crop-full':state.crop={x:0,y:0,w:1,h:1};render();break;
 case 'save-crop':state.ocrRows=Math.min(40,Math.max(3,Number(document.getElementById('ocr-rows')?.value)||12));state.ocrCols=Math.min(40,Math.max(3,Number(document.getElementById('ocr-cols')?.value)||12));state.modal='';render();break;
 case 'edit-grid':case 'edit-words':state.modal='edit';render();break;
 case 'toggle-board-edit':state.boardEdit=!state.boardEdit;if(!state.boardEdit){state.gridRaw=state.grid.map(row=>row.join(' ')).join('\n');solve();}render();break;
 case 'add-word':{const input=document.getElementById('word-new-input');const additions=splitWordBank(input?.value);const words=splitWordBank(state.wordBank);for(const w of additions)if(!words.some(x=>normalized(x)===normalized(w)))words.push(w.toLocaleUpperCase());state.wordBank=words.join('\n');render();break;}
 case 'close-modal':case 'close-cancel':case 'close-help':state.modal='';state.openMenu='';render();break;
 case 'save-grid':try{const cells=[...document.querySelectorAll('#grid-editor [data-grid-cell]')];const rows=state.grid.map((row,r)=>row.map((letter,c)=>{const input=cells.find(el=>el.dataset.gridCell===`${r}-${c}`);return normalized(input?.value||letter).slice(0,2)||letter;}));const gridRaw=rows.map(row=>row.join(' ')).join('\n');const bank=document.getElementById('word-editor')?.value||state.wordBank;const grid=parseGrid(gridRaw);state.grid=grid;state.gridRaw=gridRaw;state.wordBank=bank;state.manualCells=[];state.modal='';state.query='';state.intent=null;state.searchMatches=null;state.letterFilter='';state.selectedId='';state.visible=true;solve();render();}catch{notify(tt('invalidGrid'))}break;
 case 'help-link':case 'help-link-mobile':state.modal='help';render();break;
 case 'action-upload':case 'upload-again':document.getElementById('file-input')?.click();break;
 case 'action-analyze':analyze();break;
 case 'action-solution':exportPng();break;
 case 'action-export':exportPng();break;
 case 'reset-crop':state.crop={x:0,y:0,w:1,h:1};state.grid=[];state.gridRaw='';state.found=[];state.selectedId='';state.manualCells=[];state.modal='crop';render();break;
 case 'restore-demo':restoreDemo();break;
 case 'clear-search':case 'show-all':state.query='';state.intent=null;state.searchMatches=null;state.letterFilter='';state.selectedId='';render();break;
 }
}
document.addEventListener('click',handleClick);
document.addEventListener('submit',e=>{if(e.target.id==='generator-form'){e.preventDefault();state.createInput=document.getElementById('generator-words')?.value||'';state.createSize=state.createSize||'12';state.createDifficulty=state.createDifficulty||'medium';const words=[...new Set(splitWordBank(state.createInput).map(normalized).filter(word=>graphemes(word).length>=2))];if(words.length<2){notify(copy().needWords);return;}const size=Number(state.createSize);const generated=generateWordSearch(words,size,size,state.createDifficulty);if(!generated.placements.length){notify(copy().nonePlaced);return;}state.generated=generated;state.showGeneratedAnswers=false;state.manualCells=[];render();notify(copy().created);}});
document.addEventListener('input',e=>{if(e.target.id==='generator-words')state.createInput=e.target.value;});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();applySearch(e.target.querySelector('input').value);}});
document.addEventListener('input',e=>{if(e.target.dataset.boardCell){const [r,c]=e.target.dataset.boardCell.split('-').map(Number);const value=normalized(e.target.value).slice(0,2);if(state.grid[r]?.[c]!==undefined&&value){state.grid[r][c]=value;state.gridRaw=state.grid.map(row=>row.join(' ')).join('\n');solve();}}});
document.addEventListener('change',e=>{if(e.target.id==='file-input'){setImage(e.target.files?.[0]);e.target.value='';}});
document.addEventListener('pointerdown',e=>{const stage=e.target.closest('#crop-stage');if(stage)handleCropStart(e)});
document.addEventListener('pointermove',e=>{const stage=e.target.closest('#crop-stage')|| (dragStart&&document.getElementById('crop-stage'));if(stage)handleCropMove(e)});
document.addEventListener('pointerup',e=>{const stage=e.target.closest('#crop-stage')|| (dragStart&&document.getElementById('crop-stage'));if(stage)handleCropEnd(e)});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();e.target.closest('#dropzone').classList.add('dragging')}});
document.addEventListener('dragleave',e=>{e.target.closest('#dropzone')?.classList.remove('dragging')});
document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();setImage(e.dataTransfer?.files?.[0]);}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='word-new-input'){e.preventDefault();document.getElementById('add-word')?.click();}if(e.key==='Escape'&&(state.modal||state.openMenu)){state.modal='';state.openMenu='';render()}if((e.key==='Enter'||e.key===' ')&&e.target.id==='dropzone'){e.preventDefault();document.getElementById('file-input')?.click()}});
document.addEventListener('click',e=>{if(e.target.id==='backdrop'){state.modal='';state.openMenu='';render()}});
window.addEventListener('paste',e=>{if(e.target.matches('textarea,input'))return;const file=Array.from(e.clipboardData?.files||[]).find(x=>x.type.startsWith('image/'));if(file)setImage(file)});
if(!state.grid.length)loadDemo(state.uiLang);solve();render();
